// Extrai campos do alerta enviado pelo MNO Sentinel
const body = $input.first().json.body || $input.first().json;

return [{
  json: {
    incidentId: body.incident_id || 'inc-desconhecido',
    nodeId: body.node_id || 'node-local',
    nodeName: body.node_name || 'Servidor Local',
    alertType: body.type || 'alerta_geral',
    severity: body.severity || 'warning',
    details: body.details || 'Sem detalhes fornecidos',
    timestamp: body.timestamp || new Date().toISOString(),
    isResolution: (body.details && body.details.includes('RESOLVIDO')) || false
  }
}];

